    /// <summary>
    /// Public construct method to TMS Engine Sales order process
    /// </summary>
    /// <param name = "_tmsEngineProcess">METTMSEngineSalesOrderProcess enum</param>
    /// <param name = "_sourceRecord">Source record parameter for TMS engine</param>
    /// <param name = "_postingIdentifier">Posting identifier e.g. delivery note number</param>
    /// <returns>Instance of <c>METTMSEngineSalesOrderProccess</c></returns>
    public static METTMSEngineSalesOrderProccess construct(METTMSEngineSalesOrderProcess _tmsEngineProcess, Common _sourceRecord, str _postingIdentifier = '')
    {
        METTMSEngineSalesOrderProccess process;
        boolean error = false;
        str postingIdentifier = _postingIdentifier;

        switch (_tmsEngineProcess)
        {
            case (METTMSEngineSalesOrderProcess::Cancellation) :
                if (_sourceRecord is SalesTable)
                {
                    process = new METTMSEngineSalesOrderProccess_Cancellation(_sourceRecord);
                }
                else
                {
                    error = true;
                }
                break;

            case (METTMSEngineSalesOrderProcess::Creation) :
                if (_sourceRecord is SalesTable)
                {
                    process = new METTMSEngineSalesOrderProccess_Creation(_sourceRecord);
                }
                else
                {
                    error = true;
                }
                break;

            // Evgeniya TODO CB625

            // CB626_TMSEngineSOPackingSlip
            case (METTMSEngineSalesOrderProcess::PackingSlip) :
                if (_sourceRecord is METSalesOrderShipmentLoadHeader)
                {
                    METSalesOrderShipmentLoadHeader shipmentHeader = _sourceRecord as METSalesOrderShipmentLoadHeader;
                    
                    // Manual retrigger from shipment form
                    if (!postingIdentifier)
                    {
                        // retrieve the delivery note from the journal
                        postingIdentifier = (CustPackingSlipJour::METFindLoadShipment(shipmentHeader.LoadId, shipmentHeader.ShipmentId)).PackingSlipId;
                    }
                    
                    if (postingIdentifier)
                    {
                        process = new METTMSEngineSalesOrderProccess_PackingSlip(_sourceRecord, postingIdentifier);
                    }
                    else
                    {
                        error = true;
                    }
                }
                else
                {
                    error = true;
                }
                break;
        }

        if (error)
        {
            throw error(strFmt("@SYS19306", funcName()));
        }

        return process;
    }

    /// <summary>
    /// main method
    /// </summary>
    /// <param name = "_args">args</param>
    public static void main(Args _args)
    {
        METTMSEngineSalesOrderProcess   tmsEngineSalesOrderProcess;
        SalesTable                      salesTableLoc;
        Common common;

        if (_args.record() /*&&
            _args.record().TableId == tableNum(SalesTable)*/)
        {
            tmsEngineSalesOrderProcess = _args.parmEnum();
            common = _args.record();
            METTMSEngineSalesOrderProccess process = METTMSEngineSalesOrderProccess::construct(tmsEngineSalesOrderProcess, common);

            process.run();

            if (common is SalesTable)
            {
                salesTableLoc = common as SalesTable;
            }

            if (process.isShipmentCreated())
            {
                info(strFmt("@MET:TMSEngineSuccessMessage", salesTableLoc.SalesId));
            }
            else
            {
                info(strFmt("@MET:TMSEngineCompletedMessage", salesTableLoc.SalesId));
            }
        }
        else
        {
            throw error(strfmt("@SYS29104", funcname())); // Class %1 must be called with a buffer.
        }
    }

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(SalesTable    _salesTable)
{
    salesTable              = _salesTable;
    inventParameters        = InventParameters::find();
    carrierCode             = TMSSalesTable::find(_salesTable.SalesId).CarrierCode;
    isSalesOrderPerishable  = _salesTable.METIsSalesOrderPerishable();
    metSalesTable           = METSalesTable::findByRefRecId(salesTable.RecId);
    metInventLocation       = METInventLocation::findByInventLocationId(salesTable.InventLocationId);
    inventLocation          = InventLocation::find(salesTable.InventLocationId);
    
    isToteCustomer          = this.isToteCustomer();  
  
    // Added as never initialized
    whsPalletVolume = METInventLocation.WHSPalletVolume;
    whsPalletWeight = METInventLocation.WHSPalletWeight;
}

/// <summary>
/// Validate TMS engine in On on the warehouse
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean useTMSEngine()
{
    return metInventLocation.IsTMSEngineUsed;
}

/// <summary>
/// Validate if Perishable SOs are excluded from TMS
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean excludePerishable()
{
    return metInventLocation.ExcludePerishables;
}

/// <summary>
/// An order is perishable if it’s “Order split group” = the Inventory Parameter’s custom field “Perishable order split group”
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean SplitPerishableItems()
{
    return metInventLocation.SplitPerishableItems;
}

    /// <summary>
    /// Refactored new validate method
    /// </summary>
    /// <returns>true if valdidation successful; otherwise, false.</returns>
    protected boolean validate()
    {
        //Step 1: check if order should be excluded from TMS Engine processing
        if (!salesTable.METIsSalesOrderExcluded() &&
            carrierCode &&
            salesTable.METRoute &&
            this.useTMSEngine() &&
            (!isSalesOrderPerishable ||
            (isSalesOrderPerishable  && !this.excludePerishable())))
        {
            return true;
        }

        return false;
    }

/// <summary>
/// New method to retrieve the METTMSShipmentOrderTable
/// For creation, straight forward with sales order number
/// Overridden in child classes for packing slip
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(SalesIdBase _salesId, WMSPickingRouteID _pickingRouteId = '')
{
    return METTMSShipmentOrderTable::findByOrder(_salesId, _pickingRouteId);
}

    /// <summary>
    /// Run the TMS engine
    /// </summary>
    public void run()
    {
        METTMSShipmentTable         tmsShipmentTable;
        METTMSShipmentTable         tmsShipmentTableCancel;
        METTMSShipmentOrderTable    tmsShipmentOrderTable;

        //Step 1: check if order should be excluded from TMS Engine processing
        if (this.validate())
        {
            this.initTmpTable();
            try
            {
                ttsbegin;

                tmsShipmentOrderTable   = this.getTMSShipmentOrderTable(salesTable.SalesId);
                //Step 2: Check if the order is already on a shipment
                if (!tmsShipmentOrderTable.RecId)
                {
                    //Step 3: If order is not on any existing shipment
                    tmsShipmentTable = this.initTMSShipment();
               
                    //Step 3a: check if there is an existing shipment this order can be made part of.
                    if (!tmsShipmentTable.RecId)
                    {
                        this.createShipment();
                    }
                    else
                    {
                        //Step 3c: If a shipment exists, update it
                        this.createShipment(false);
                    }
                }
                else
                {
                    this.initTMSShipment();
                    //Step 4: If order is on an existing shipment and there is a change to either Route or Ship date
                    if (tmsShipmentOrderTable.ShipmentId != shipmentId)
                    {
                        //Step 4a: Get the “TMS Shipment” record related to the “TMS Shipment Order”
                        tmsShipmentTableCancel = METTMSShipmentTable::find(tmsShipmentOrderTable.ShipmentId);

                        //Step 4c: Update the current “TMS Shipment” - cancel it
                        this.cancelShipment(salesTable.SalesId);

                        //Step 4d: Link the sales order to a new shipment
                        this.createShipment();
                    
                    }
                    else
                    {
                        //Step 5: If order is on an existing shipment and there is no change to both Route and Ship date
                        //delete Shipment itemgroup - recreate
                        delete_from tmsShipmentOrderTable
                            where tmsShipmentOrderTable.ShipmentId == shipmentId;
                        //Step 3d: Create TMS Shipment Order record
                        //Step 4d: Link the sales order to a new shipment
                        this.createShipment(false);
                    }
                }

                //Step 6: Update order and shipment totals
                //Step 6a: Update the order’s “Order weight”
                //Step 6b: Update the order’s “Order volume”
                //Step 6c: Update order’s “Pallet Total footprint”
                this.updateTMSShipmentOrder();

                //Step 6d: Update the shipment’s “Pallet lifts”
                this.updateTMSShipment();

                ttscommit;
            }
            catch (Exception::Error)
            {
                //An error occurs during the creation or updates of the staging records
                error(strFmt("@MET:TMSEngineSalesOrderProcessCreation", salesTable.SalesId));
            }
        }
    }

    /// <summary>
    /// Initialise temporary table with calculations
    /// </summary>
    void initTmpTable()
    {        
        splitGroupTable = MetSplitGroupTable::find(metSalesTable.OrderSplitGroup);
        this.initRepackQtyFactor();

        QueryRun qr = new QueryRun(this.initSalesLineQuery());

        while (qr.next())
        {
            this.createTempTableRecords(qr);
        }
    }

    /// <summary>
    /// Initialise the sales order line query
    /// </summary>
    /// <returns><c>Query</c> object</returns>
    Query initSalesLineQuery()
    {
        Query query = new Query();
        QueryBuildDataSource qbds = query.addDataSource(tableNum(SalesLine));

        qbds.addRange(fieldNum(SalesLine, SalesId)).value(queryValue(salesTable.SalesId));
        // Exclude canceled lines
        qbds.addRange(fieldNum(SalesLine, SalesStatus)).value(SysQuery::valueNot(SalesStatus::Canceled));
        qbds.addRange(fieldNum(SalesLine, Blocked)).value(queryValue(NoYes::No));

        return query;
    }

    /// <summary>
    /// If the item on the sales line has a Product attribute listed in the new setup table, set IsKegItem = Yes
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <returns><c>boolean</c> object</returns>
    private boolean isKegItem(ItemId    _itemId)
    {
        EcoResProductInstanceValue      ecoResProductInstanceValue;
        METAttributeIdentifiers         attributeIdentifiers;
        InventTable                     inventTable;
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;

        select firstonly crosscompany RecId from inventTable
            where inventTable.ItemId == _itemId
            join  RecId from ecoResProductInstanceValue
            where   ecoResProductInstanceValue.Product == inventTable.Product
            join InstanceRecId from attributeValuesTable
                where   attributeValuesTable.InstanceRecId == ecoResProductInstanceValue.RecId
                exists join attributeIdentifiers
                    where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                        &&  attributeIdentifiers.AttributeValueText == attributeValuesTable.TextValue
                        &&  attributeIdentifiers.AttributeValueText != ''
                        &&  attributeIdentifiers.AttributeSource == METAttributeSource::Product
                        &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::Keg;

        return inventTable.RecId;
    }

    /// <summary>
    /// If customer is TOTE customer
    /// </summary>
    /// <returns><c>boolean</c> object</returns>
    private boolean isToteCustomer()
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == salesTable.CustAccount
            && instanceValue.CustomerDataAreaId == salesTable.DataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeValueText == attributeValuesTable.TextValue
                    &&  attributeIdentifiers.AttributeValueText != ''
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }

    /// <summary>
    /// To check if the customer has Tote type (attribute type) defined under inventory parameters > Metcash > Attribute identifiers
    /// </summary>
    /// <returns>True if the customer has Tote type (attribute type); otherwise, false.</returns>
    boolean hasCustomerToteAttributeType()
    {
        RetailEcoResInstanceAttributeValuesView attributeValuesTable;
        CustomerInstanceValue   instanceValue;
        METAttributeIdentifiers attributeIdentifiers;

        select firstonly crosscompany RecId from instanceValue
            where instanceValue.AccountNum == salesTable.CustAccount
            && instanceValue.CustomerDataAreaId == salesTable.DataAreaId;

        select firstonly InstanceRecId from attributeValuesTable
            where   attributeValuesTable.InstanceRecId == instanceValue.RecId
            exists join attributeIdentifiers
                where   attributeIdentifiers.Attribute == attributeValuesTable.AttributeDefinitionRecId
                    &&  attributeIdentifiers.AttributeSource == METAttributeSource::Customer
                    &&  attributeIdentifiers.AttributeIdentifier == METAttributeIdentifier::TOTE;

        return attributeValuesTable.InstanceRecId;
    }

    /// <summary>
    /// get line commodity value
    /// </summary>
    /// <param name = "_isTobaccoItem">isTobaccoItem</param>
    /// <param name = "_filterNum">WHSFilterNum</param>
    /// <returns><c>METTMSCommodity</c> object</returns>
    private METTMSCommodity getLineCommodity(boolean _isTobaccoItem,WHSFilterNum  _filterNum)
    {
        METTMSCommodity ret;

        if (_IsTobaccoItem)
        {
            return tobCommodity;
        }
        else if(this.SplitPerishableItems())
        {
            ret = (select WHSFilters where WHSFilters.FilterNum == _filterNum).METTMSCommodity;
        }
        if (!ret)
        {
            ret = splitGroupTable.TMSCommodity;
        }

        return ret;
    }

    /// <summary>
    /// init tobaccoRepackQtyFactor and standardRepackQtyFactor
    /// </summary>
    void initRepackQtyFactor()
    {
        METContainerTypeTable   containerTypeTable;

        //default values when no containerTypeTable
        tobaccoRepackQtyFactor = tobaccoRepackQtyFactorDefault;
        standardRepackQtyFactor = standardRepackQtyFactorDefault;

        if (this.hasCustomerToteAttributeType())
        {
            // Tote customer search for Plastic (tote) container ID else Cardboard container ID
            WHSContainerTypeCode containerTypeCode = isToteCustomer ? inventParameters.METPlasticContainerID : inventParameters.METCardboardContainerID;
            
            containerTypeTable   = METContainerTypeTable::find(containerTypeCode, salesTable.InventLocationId);
            if (containerTypeTable)
            {
                tobaccoRepackQtyFactor  = containerTypeTable.TobaccoRepackQty;
                standardRepackQtyFactor = containerTypeTable.GroceryRepackQty;
                //whsPalletVolume = containerTypeTable.ContainerVolume; //Added as never initialise in class
            }
        }
        // only when the customer doesn't have "Tote type" attribute type set repack qty to 1
        else
        {
            tobaccoRepackQtyFactor = 1;
            standardRepackQtyFactor = 1;                       
        }
    }

    /// <summary>
    /// init values from Container type
    /// </summary>
    void initValuesFromContainerType()
    {
        METContainerTypeTable   containerTypeTable;
        containerTypeTable   = METContainerTypeTable::find(inventParameters.METCardboardContainerID, salesTable.InventLocationId);
        whsCaseVolume   = containerTypeTable.ContainerVolume;

        containerTypeTable   = METContainerTypeTable::find(inventParameters.METPlasticContainerID, salesTable.InventLocationId);
        whsToteVolume   = containerTypeTable.ContainerVolume;
        whsToteWeight   = containerTypeTable.Weight;
    }

    /// <summary>
    /// get KegQtyUOM
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <returns><c>string value</c> object</returns>
    str getKegQtyUOM(ItemId _itemId)
    {
        str kegQtyUOM;
        METInventTable  metInventTable;

        select firstonly BottleSize from metInventTable
            where metInventTable.ItemId == _itemId;
        if (metInventTable.BottleSize)
        {
            kegQtyUOM   = strFmt('%1', metInventTable.BottleSize);
            //kegQtyUOM   = strFmt('@MET:KegQtyUOM',strRem(kegQtyUOM, '.'));
            kegQtyUOM   = strFmt('K%1',strRem(kegQtyUOM, '.'));
        }

        return kegQtyUOM;
    }

    /// <summary>
    /// get LineUnitVolume and LineUnitWeight
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_inventDim">InventDim</param>
    /// <param name = "_uom">WHSUOM</param>
    /// <returns><c>container</c> object</returns>
    container getLineUnitVolumeWeight(ItemId    _itemId,
                                InventDim       _inventDim,
                                WHSUOM          _uom)
    {
        METWHSPhysDimUOMSite    metWHSPhysDimUOMSite;
        WHSPhysDimUOM           whsPhysDimUOM;
        METUOMVolume            volume;
        Weight                  weight;
        WHSUOM                  warehouseUnit;

        select firstonly * from metWHSPhysDimUOMSite
            where metWHSPhysDimUOMSite.ItemId == _itemId
            && metWHSPhysDimUOMSite.UOM == _uom
            && metWHSPhysDimUOMSite.SiteId == _inventDim.InventSiteId;

        volume  = metWHSPhysDimUOMSite.displayVolume();
        weight  = metWHSPhysDimUOMSite.Weight;

        if (!volume || !weight)
        {
            warehouseUnit   = METInventLocation::getWarehouseUnit(_itemId, _inventDim);

            select firstonly * from whsPhysDimUOM
                where whsPhysDimUOM.ItemId == _itemId
                && whsPhysDimUOM.UOM == warehouseUnit;

            volume  = volume ? volume : whsPhysDimUOM.metDisplayVolume();
            weight  = weight ? weight : metWHSPhysDimUOMSite.Weight;
        }

        return [volume, weight];
    }

    /// <summary>
    /// cancel TMS shipment
    /// </summary>
    /// <param name = "_salesId">SalesId</param>
    void cancelShipment(SalesId _salesId)
    {
        METTMSShipmentTable         tmsShipmentTable;
        METTMSShipmentOrderTable    tMSShipmentOrderTable;
        METTMSShipmentOrderTable    tMSShipmentOrderTableExist;

        ttsbegin;
        select firstonly forupdate tMSShipmentOrderTable
                    where tMSShipmentOrderTable.OrderNumber == _salesId;
        if (tMSShipmentOrderTable.RecId)
        {
            tMSShipmentTable = METTMSShipmentTable::find(tMSShipmentOrderTable.ShipmentId, true);
            tMSShipmentOrderTable.delete();

            tMSShipmentTable.TMSSendStatus = METTMSSendStatus::ToBeSent;

            select firstonly RecId from tMSShipmentOrderTableExist
                        where tMSShipmentOrderTableExist.ShipmentId == tMSShipmentTable.ShipmentID
                        && tMSShipmentOrderTableExist.RecId != tMSShipmentOrderTable.RecId;
            if (!tMSShipmentOrderTableExist.RecId)
            {
                        
                tMSShipmentTable.ShipmentStatus = METCashShipmentStatus::Cancelled;
            }
            tMSShipmentTable.update();
        }
        ttscommit;
    }

/// <summary>
/// Return if shipment created/updated
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
private boolean isShipmentCreated()
{
    return shipmentCreated;
}

    /// <summary>
    /// create tms shipment tables
    /// </summary>
    /// <param name = "_isCreateTMSShipment">boolean</param>
    protected void createShipment(boolean     _isCreateTMSShipment = true)
    {
        METTMSShipmentOrderTable    tmsShipmentOrderTable;
        METTMSShipmentTable         tmsShipmentTable;

        //Step 3b: If no shipment exists, create a new one
        if (_isCreateTMSShipment)
        {
            this.createTMSShipment();
        }
        //Step 3d: Create TMS Shipment Order record
        tmsShipmentOrderTable = this.createTMSShipmentOrder();
        //Step 3e: Create TMS Shipment Item Group records
        this.createTMSShipmentItemGroup(tmsShipmentOrderTable.TMSShipmentOrderIdentifier);
    }

    /// <summary>
    /// Step 3a: check if there is an existing shipment this order can be made part of.
    /// </summary>
    /// <returns>Instance of <c>METTMSShipmentTable</c></returns>
    protected METTMSShipmentTable initTMSShipment()
    {
        str     shippingDateStr;

        shippingDate = metSalesTable.SecondShipDate ? metSalesTable.SecondShipDate :
            salesTable.ShippingDateConfirmed ? salesTable.ShippingDateConfirmed :
            salesTable.ShippingDateRequested;

        shippingDateStr = date2Str
            (shippingDate,
                321,
                DateDay::Digits2,
                DateSeparator::None,
                DateMonth::Digits2,
                DateSeparator::None,
                DateYear::Digits4);

        shipmentId  = strFmt("@MET:ShipmentStrFmt", salesTable.InventLocationId, salesTable.CustAccount, salesTable.METRoute, shippingDateStr);

        return METTMSShipmentTable::find(shipmentId);
    }

/// <summary>
/// init Delivery date
/// </summary>
private void initDeliveryDate()
{
    deliveryDate = SalesTable.ReceiptDateConfirmed ? SalesTable.ReceiptDateConfirmed : SalesTable.ReceiptDateRequested;
}

/// <summary>
/// Step 3b: If no shipment exists, create a new one
/// </summary>
protected void createTMSShipment()
{
    METTMSShipmentTable tmsShipmentTable;
    
    this.setTMSShipmentFields(tmsShipmentTable);
    tmsShipmentTable.insert();
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentTable</c> record
/// </summary>
/// <param name = "_tmsShipmentTable"><c>METTMSShipmentTable</c> record</param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    METRouteStopTable   routeStopTable = METRouteStopTable::findByRouteIdentifier(metSalesTable.OriginalSecondRouteStopIdentifier ? metSalesTable.OriginalSecondRouteStopIdentifier : metSalesTable.OriginalRouteStopIdentifier);
    METRouteTable       routeTable = METRouteTable::findByRouteIdentifier(metSalesTable.OriginalSecondRouteIdentifier ? metSalesTable.OriginalSecondRouteIdentifier : metSalesTable.OriginalRouteIdentifier);
    
    _tmsShipmentTable.ShipmentID = shipmentId;
    _tmsShipmentTable.SourceWarehouse = salesTable.InventLocationId;
    _tmsShipmentTable.DestinationType = METDestinationType::Customer;
    _tmsShipmentTable.DestinationCustomer = salesTable.CustAccount;
    _tmsShipmentTable.DestinationWarehouse = '';
    _tmsShipmentTable.Route = salesTable.METRoute;
    _tmsShipmentTable.ConfirmedShipDate  = shippingDate;
    _tmsShipmentTable.TMSSendStatus = METTMSSendStatus::ToBeSent;
    _tmsShipmentTable.ShipmentStatus = METCashShipmentStatus::Active;
    _tmsShipmentTable.RouteStop = int2str(salesTable.METRouteStopNum);
    _tmsShipmentTable.WarehouseZone = routeStopTable.Zone ? routeStopTable.Zone : routeTable.Zone;
    _tmsShipmentTable.StagingLane = metSalesTable.StagingLaneId;
    _tmsShipmentTable.PickupEarliest = routeTable.ReadyTime;
    _tmsShipmentTable.PickupLatest = routeTable.DispatchTime;
    _tmsShipmentTable.DeliveryEarliest = routeStopTable.TimeWindowStart;
    _tmsShipmentTable.DeliveryLatest = routeStopTable.TimeWindowEnd;
    _tmsShipmentTable.Carrier = carrierCode;
    _tmsShipmentTable.SpecialDeliveryInstructions = this.getCustomerInstruction();
    _tmsShipmentTable.DeliveryNoteNumber = '';
    _tmsShipmentTable.ChepPalletCount    = 0;
    _tmsShipmentTable.LoscamPalletCount  = 0;
    _tmsShipmentTable.PlainPalletCount   = 0;
}

    /// <summary>
    /// init Customer instruction
    /// </summary>
    /// <returns>value for <c>METCustomerInstruction</c></returns>
    private METCustomerInstruction getCustomerInstruction()
    {
        METWarehouseCarrierCustomerView warehouseCarrierCustomerView;
        TransDate                       today = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

        select firstonly CustomerInstruction from warehouseCarrierCustomerView
            where warehouseCarrierCustomerView.CustAccount == salesTable.CustAccount
                && warehouseCarrierCustomerView.StartDate <= today
                && warehouseCarrierCustomerView.EndDate >= today;

        return warehouseCarrierCustomerView.CustomerInstruction;
    }

    /// <summary>
    /// Step 3c: If a shipment exists, update it
    /// </summary>
    void updateTMSShipment()
    {
        METTMSShipmentTable         tmsShipmentTable;
        METTMSShipmentOrderTable    tmsShipmentOrderTable;

        // calc sum PalletTotalFootprint for the shipment
        select sum(PalletTotalFootprint) from tmsShipmentOrderTable
                where tmsShipmentOrderTable.ShipmentId == shipmentId;

        update_recordset tmsShipmentTable
            setting TMSSendStatus = METTMSSendStatus::ToBeSent,
                    ShipmentStatus = METCashShipmentStatus::Active,
                    PalletLifts = tmsShipmentOrderTable.PalletTotalFootprint
            // VNG join sum doesn't seem to work with update_recordset
              where tmsShipmentTable.ShipmentID == shipmentId;
        /*join sum(PalletTotalFootprint) from tmsShipmentOrderTable
                where tmsShipmentOrderTable.ShipmentId == tmsShipmentTable.ShipmentID 
                   && tmsShipmentOrderTable.OrderNumber == salesTable.SalesId;
                   && tmsShipmentOrderTable.ShipmentId == _tmsShipmentId;*/

    }

    /// <summary>
    /// Step 3d: Create TMS Shipment Order record
    /// </summary>
    /// <returns>Instance of <c>METTMSShipmentOrderTable</c></returns>
    METTMSShipmentOrderTable createTMSShipmentOrder()
    {
        METTMSShipmentOrderTable    tmsShipmentOrderTable;
    
        this.setTMSShipmentOrderFields(tmsShipmentOrderTable);
        tmsShipmentOrderTable.insert();

        return tmsShipmentOrderTable;
    }

    /// <summary>
    /// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
    /// </summary>
    /// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
    protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
    {
        _tmsShipmentOrderTable.initValue();
        _tmsShipmentOrderTable.ShipmentId = shipmentId;
        _tmsShipmentOrderTable.OrderNumber = salesTable.SalesId;
        _tmsShipmentOrderTable.IsCrossDockOrder = NoYes::No;

        // Vincent change
        METTMSEngineSalesOrderProccessLinesTmp  linesTmp;
        linesTmp.linkPhysicalTableInstance(proccessLinesTmp);
        select sum(BrokenCasesCountNonSecurity), sum(BrokenCasesCountSecurity), sum(RepackCountNonSecurity), sum(RepackCountSecurity) from linesTmp;

        /*_tmsShipmentOrderTable.BrokenCaseItemQtySecurity = this.getBrokenCasesCountSecurity();
        _tmsShipmentOrderTable.BrokenCaseItemQtyNonSecurity = this.getBrokenCasesCountNonSecurity();
        _tmsShipmentOrderTable.RepackCaseCountSecurity = tobaccoRepackQtyFactor ? _tmsShipmentOrderTable.BrokenCaseItemQtySecurity/tobaccoRepackQtyFactor : 0;
        _tmsShipmentOrderTable.RepackCaseCountNonSecurity = standardRepackQtyFactor ? _tmsShipmentOrderTable.RepackCaseCountNonSecurity/standardRepackQtyFactor : 0;*/
        _tmsShipmentOrderTable.BrokenCaseItemQtySecurity = linesTmp.BrokenCasesCountSecurity;
        _tmsShipmentOrderTable.BrokenCaseItemQtyNonSecurity = linesTmp.BrokenCasesCountNonSecurity;
        _tmsShipmentOrderTable.RepackCaseCountSecurity = linesTmp.RepackCountSecurity;
        _tmsShipmentOrderTable.RepackCaseCountNonSecurity = linesTmp.RepackCountNonSecurity;

        _tmsShipmentOrderTable.CaseCountShipped = _tmsShipmentOrderTable.BrokenCaseItemQtyNonSecurity + this.getRepackContainersByCommodity();
        _tmsShipmentOrderTable.CaseCountSecurity = _tmsShipmentOrderTable.RepackCaseCountSecurity;
        _tmsShipmentOrderTable.SSCC = '';
        _tmsShipmentOrderTable.XDockWMSUpdateReceived = NoYes::No;
        _tmsShipmentOrderTable.VendorNumber = '';
    }

    /// <summary>
    /// get BrokenCasesCountSecurity
    /// </summary>
    /// <returns>Qty <c>Qty</c></returns>
    private Qty getBrokenCasesCountSecurity()
    {
        METTMSEngineSalesOrderProccessLinesTmp  linesTmp;
        linesTmp.linkPhysicalTableInstance(proccessLinesTmp);
        
        /*select sum(SalesQty) from linesTmp
            where linesTmp.IsTobaccoItem == NoYes::Yes;*/
        select sum(BrokenCasesCountSecurity) from linesTmp;

        return linesTmp.SalesQty;
    }

    /// <summary>
    /// get BrokenCasesCountNonSecurity
    /// </summary>
    /// <returns>Qty <c>Qty</c></returns>
    private Qty getBrokenCasesCountNonSecurity()
    {
        METTMSEngineSalesOrderProccessLinesTmp  linesTmp;
        linesTmp.linkPhysicalTableInstance(proccessLinesTmp);

        //select sum(CaseQty_CaseLines) from linesTmp;
        select sum(BrokenCasesCountNonSecurity) from linesTmp;

        return linesTmp.CaseQty_CaseLines;
    }

    /// <summary>
    /// RepackContainersByCommodity = RoundUp the sum of (RepackCountSecurity + RepackCountNonSecurity) for all the lines on the order per LineCommodity
    /// </summary>
    /// <returns>int <c>Int</c></returns>
    private int getRepackContainersByCommodity()
    {
        METTMSEngineSalesOrderProccessLinesTmp  processLinesGroup;
        METTMSEngineSalesOrderProccessLinesTmp  proccessLines;
        int     ret;

        processLinesGroup.linkPhysicalTableInstance(proccessLinesTmp);
        proccessLines.linkPhysicalTableInstance(proccessLinesTmp);

        while select processLinesGroup
            group by LineCommodity
        {
            select sum(RepackCountSecurity), sum(RepackCountNonSecurity) from proccessLines
                where  proccessLines.LineCommodity == processLinesGroup.LineCommodity;

            ret += roundUp(proccessLines.RepackCountSecurity + proccessLines.RepackCountNonSecurity, 1);
        }

        return ret;
    }

    /// <summary>
    /// get BrokenCasesCountNonSecurityByCommodity
    /// </summary>
    /// <returns>Qty <c>Qty</c></returns>
    private Qty getBrokenCasesCountNonSecurityByCommodity()
    {
        METTMSEngineSalesOrderProccessLinesTmp  processLinesGroup;
        METTMSEngineSalesOrderProccessLinesTmp  proccessLines;
        int     ret;

        processLinesGroup.linkPhysicalTableInstance(proccessLinesTmp);
        proccessLines.linkPhysicalTableInstance(proccessLinesTmp);

        while select processLinesGroup
            group by LineCommodity
        {
            select sum(SalesQty) from proccessLines
                where   proccessLines.IsTobaccoItem == NoYes::No
                    &&  proccessLines.IsKegItem == NoYes::No
                    &&  proccessLines.SalesUnit == unitEA
                    &&  proccessLines.LineCommodity == processLinesGroup.LineCommodity;
            
            ret += roundUp(proccessLines.SalesQty, 1);
        }
        return ret;
    }

    /// <summary>
    /// Step 3e: Create TMS Shipment Item Group records
    /// </summary>
    /// <param name = "_tmsShipmentOrderIdentifier">METTMSShipmentOrderIdentifier</param>
    void createTMSShipmentItemGroup(METTMSShipmentOrderIdentifier   _tmsShipmentOrderIdentifier)
    {
        METTMSEngineSalesOrderProccessLinesTmp  processLinesGroup;

        processLinesGroup.linkPhysicalTableInstance(proccessLinesTmp);

        while select sum(CaseQty_CaseLines),
                    sum(RepackCountSecurity),
                    sum(RepackCountNonSecurity),
                    sum(LineWeight_CaseLines),
                    sum(LineWeight_BrokenCaseSecurity),
                    sum(LineWeight_BrokenCaseNonSecurity),
                    sum(LineVolume_CaseLines),
                    sum(LineVolume_BrokenCaseSecurity),
                    sum(LineVolume_BrokenCaseNonSecurity),
                    sum(SalesQty)
        from processLinesGroup
            group by LineCommodity
        {
            if (!isToteCustomer && (processLinesGroup.CaseQty_CaseLines + processLinesGroup.RepackCountSecurity + processLinesGroup.RepackCountNonSecurity) > 0
                || processLinesGroup.CaseQty_CaseLines > 0)
            {
                this.createTMSShipmentItemGroupByUOM(unitCSE, processLinesGroup, _tmsShipmentOrderIdentifier);
            }

            if (isToteCustomer && (processLinesGroup.RepackCountSecurity + processLinesGroup.RepackCountNonSecurity)>0)
            {
                this.createTMSShipmentItemGroupByUOM(unitTOT, processLinesGroup, _tmsShipmentOrderIdentifier);
            }
            
        }

        while select sum(CaseQty_CaseLines),
                    sum(RepackCountSecurity),
                    sum(RepackCountNonSecurity),
                    sum(LineWeight_CaseLines),
                    sum(LineWeight_BrokenCaseSecurity),
                    sum(LineWeight_BrokenCaseNonSecurity),
                    sum(LineVolume_CaseLines),
                    sum(LineVolume_BrokenCaseSecurity),
                    sum(LineVolume_BrokenCaseNonSecurity),
                    sum(SalesQty)
        from processLinesGroup
            group by LineCommodity, IsKegItem
            where processLinesGroup.IsKegItem == NoYes::No
        {
            this.createTMSShipmentItemGroupByUOM(unitPAL, processLinesGroup, _tmsShipmentOrderIdentifier);
        }
        
        while select sum(SalesQty),
                    sum(CaseQty_CaseLines),
                    sum(RepackCountSecurity),
                    sum(RepackCountNonSecurity),
                    sum(LineWeight_CaseLines),
                    sum(LineWeight_BrokenCaseSecurity),
                    sum(LineWeight_BrokenCaseNonSecurity),
                    sum(LineVolume_CaseLines),
                    sum(LineVolume_BrokenCaseSecurity),
                    sum(LineVolume_BrokenCaseNonSecurity),
                    sum(SalesQty)
        from processLinesGroup
            group by LineCommodity, KegQtyUOM
            where processLinesGroup.KegQtyUOM  != ''
            && processLinesGroup.IsKegItem == NoYes::Yes
        {
            this.createTMSShipmentItemGroupByUOM(processLinesGroup.KegQtyUOM , processLinesGroup, _tmsShipmentOrderIdentifier);
        }

        while select sum(CaseQty_CaseLines),
                    sum(RepackCountSecurity),
                    sum(RepackCountNonSecurity),
                    sum(LineWeight_CaseLines),
                    sum(LineWeight_BrokenCaseSecurity),
                    sum(LineWeight_BrokenCaseNonSecurity),
                    sum(LineVolume_CaseLines),
                    sum(LineVolume_BrokenCaseSecurity),
                    sum(LineVolume_BrokenCaseNonSecurity),
                    sum(SalesQty)
        from processLinesGroup
            group by LineCommodity, IsKegItem
            where processLinesGroup.IsKegItem == NoYes::Yes
        {
            this.createTMSShipmentItemGroupByUOM(unitPAL, processLinesGroup, _tmsShipmentOrderIdentifier, NoYes::Yes);
        }
    }

    /// <summary>
    /// Step 3e: Create TMS Shipment Item Group records
    /// </summary>
    /// <param name = "_shipmentUOM">METShipmentUOM</param>
    /// <param name = "_lineTmp">METTMSEngineSalesOrderProccessLinesTmp</param>
    /// <param name = "_tmsShipmentOrderIdentifier">METTMSShipmentOrderIdentifier</param>
    /// <param name = "_isKegItem">boolean</param>
    void createTMSShipmentItemGroupByUOM(METShipmentUOM                         _shipmentUOM,
                                        METTMSEngineSalesOrderProccessLinesTmp  _lineTmp,
                                        METTMSShipmentOrderIdentifier           _tmsShipmentOrderIdentifier,
                                        boolean                                 _isKegItem = false)
    {
        
        METTMSShipmentItemGroup     tmsShipmentItemGroup;
        int                         repackContainersByCommodity;

        repackContainersByCommodity = roundUp(_lineTmp.RepackCountSecurity, 1) + roundUp(_lineTmp.RepackCountNonSecurity, 1);

        tmsShipmentItemGroup.clear();
        tmsShipmentItemGroup.initValue();
        tmsShipmentItemGroup.TMSShipmentOrderIdentifier = _tmsShipmentOrderIdentifier;
        tmsShipmentItemGroup.QuantityUOM = _shipmentUOM;
        tmsShipmentItemGroup.Commodity  = _lineTmp.LineCommodity;
        switch (_shipmentUOM)
        {
            case unitCSE :
                tmsShipmentItemGroup.Quantity   = isToteCustomer ? _lineTmp.CaseQty_CaseLines : (_lineTmp.CaseQty_CaseLines + repackContainersByCommodity);
                tmsShipmentItemGroup.Weight     =  isToteCustomer ? _lineTmp.LineWeight_CaseLines : (_lineTmp.LineWeight_CaseLines + _lineTmp.LineWeight_BrokenCaseSecurity + _lineTmp.LineWeight_BrokenCaseNonSecurity);
                tmsShipmentItemGroup.Cube       = isToteCustomer ? _lineTmp.LineVolume_CaseLines : (_lineTmp.LineVolume_CaseLines + /*whsPalletVolume*/whsCaseVolume * repackContainersByCommodity);
                break;

            case unitTOT :
                tmsShipmentItemGroup.Quantity   = repackContainersByCommodity;
                tmsShipmentItemGroup.Weight     =  _lineTmp.LineWeight_BrokenCaseSecurity + _lineTmp.LineWeight_BrokenCaseNonSecurity + whsToteWeight * tmsShipmentItemGroup.Quantity;
                tmsShipmentItemGroup.Cube       = whsToteVolume * tmsShipmentItemGroup.Quantity;
                break;

            case unitPAL :
                if (_isKegItem)
                {
                    tmsShipmentItemGroup.Quantity   = inventParameters.METKegsPerPallet ? decRound(_lineTmp.SalesQty / inventParameters.METKegsPerPallet, 2) : 0;
                    tmsShipmentItemGroup.Weight     = _lineTmp.LineWeight_Kegs + decRound(tmsShipmentItemGroup.Quantity,0) * whsPalletWeight;
                    tmsShipmentItemGroup.Cube       = _lineTmp.LineVolume_Kegs;
                }
                else
                {
                    tmsShipmentItemGroup.Cube       = isToteCustomer ? (_lineTmp.LineVolume_CaseLines + whsToteVolume * RepackContainersByCommodity): (_lineTmp.LineVolume_CaseLines + whsCaseVolume * repackContainersByCommodity);
                    tmsShipmentItemGroup.Quantity   = whsPalletVolume ? tmsShipmentItemGroup.Cube/whsPalletVolume : 0;
                    tmsShipmentItemGroup.Weight     =  _lineTmp.LineWeight_CaseLines + _lineTmp.LineWeight_BrokenCaseSecurity + _lineTmp.LineWeight_BrokenCaseNonSecurity + decRound(tmsShipmentItemGroup.Quantity, 0) * whsPalletWeight;
                }
                if (tmsShipmentItemGroup.Quantity < 0.01)
                {
                    tmsShipmentItemGroup.Quantity = 0.01;
                }
                break;

            case _lineTmp.KegQtyUOM :
                tmsShipmentItemGroup.Quantity   = _lineTmp.SalesQty;
                tmsShipmentItemGroup.Weight     = _lineTmp.LineWeight_Kegs;
                tmsShipmentItemGroup.Cube       = _lineTmp.LineVolume_Kegs;
                break;
        }
        tmsShipmentItemGroup.IsRatingUnit = this.isRatingUnit(_shipmentUOM);
        tmsShipmentItemGroup.insert();

        shipmentCreated = true;
    }

/// <summary>
/// return Rating unit
/// </summary>
/// <param name = "_shipmentUOM">METShipmentUOM</param>
/// <returns>boolean <c>boolean</c></returns>
private boolean isRatingUnit(METShipmentUOM _shipmentUOM)
{
    return METTMSShipmentRatingUnit::find(SalesTable.InventLocationId, _shipmentUOM).RecId;
}

    /// <summary>
    /// Step 6a: Update the order’s “Order weight”
    /// Step 6b: Update the order’s “Order volume”
    /// Step 6c: Update order’s “Pallet Total footprint”
    /// </summary>
    void updateTMSShipmentOrder()
    {
        METTMSShipmentOrderTable    tmsShipmentOrderTable;
        METTMSShipmentItemGroup     tmsShipmentItemGroup;

        update_recordset tmsShipmentOrderTable
            setting OrderWeight = tmsShipmentItemGroup.Weight,
                    OrderVolume = tmsShipmentItemGroup.Cube
            join sum(Weight), sum(Cube) from tmsShipmentItemGroup
                where tmsShipmentOrderTable.ShipmentId == shipmentId
                    && tmsShipmentOrderTable.OrderNumber == salesTable.SalesId
                    && tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                    && (tmsShipmentItemGroup.QuantityUOM == unitCSE
                    || tmsShipmentItemGroup.QuantityUOM like "@MET:KegQtyUOM"
                    || tmsShipmentItemGroup.QuantityUOM == unitTOT);

        update_recordset tmsShipmentOrderTable
            setting PalletTotalFootprint = tmsShipmentItemGroup.Quantity
            join sum(Quantity) from tmsShipmentItemGroup
                where tmsShipmentOrderTable.ShipmentId == shipmentId
                    && tmsShipmentOrderTable.OrderNumber == salesTable.SalesId
                    && tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                    && tmsShipmentItemGroup.QuantityUOM == unitPal;
    }

/// <summary>
/// Manages the lineShipQty variable
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <returns>Sales order quantity</returns>
Qty lineShipQty(SalesLine   _salesLine)
{
    return _salesLine.SalesQty;
}

/// <summary>
/// Get tables from _queryRun object used to fill the temp table
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object used to fill the temp table</param>
/// <returns>Container of records from the <c>QueryRun</c> object</returns>
protected container getTablesQueryRun(QueryRun _queryRun)
{
    return [_queryRun.get(tableNum(SalesLine))];
}

/// <summary>
/// Method to create the METTMSEngineSalesOrderProccessLinesTmp records from the QueryRun
/// </summary>
/// <param name = "_queryRun"><c>QueryRun</c> object</param>
protected void createTempTableRecords(QueryRun _queryRun)
{
    SalesLine   salesLine;
    
    [salesLine] = this.getTablesQueryRun(_queryRun);
    
    this.createLineTmp(salesLine);
}

    /// <summary>
    /// Method to initialise the METTMSEngineSalesOrderProccessLinesTmp temp record from SalesLine
    /// </summary>
    /// <param name = "_salesLine">Sales order line</param>
    protected void createLineTmp(SalesLine _salesLine)
    {
        METInventItemOrderSetup     metInventItemOrderSetup;

        proccessLinesTmp.clear();
        proccessLinesTmp.ItemId     = _salesLine.ItemId;
        proccessLinesTmp.SalesId    = _salesLine.SalesId;
        proccessLinesTmp.SalesUnit  = _salesLine.SalesUnit;
        proccessLinesTmp.SalesQty   = this.lineShipQty(_salesLine);
        //if the Sale line’s Item Type = Inventory & Warehouse Management Parameters’ “Tobacco Metcash item type” set IsTobaccoItem = Yes
        select firstonly ItemType, FilterCode from metInventItemOrderSetup
                where  metInventItemOrderSetup.SiteId == _salesLine.inventDim().InventSiteId
                    && metInventItemOrderSetup.ItemId == _salesLine.ItemId;

        //METTobaccoItemType should not be blank
        proccessLinesTmp.IsTobaccoItem = (metInventItemOrderSetup.ItemType == inventParameters.METTobaccoItemType && inventParameters.METTobaccoItemType != '') ? NoYes::Yes : NoYes::No;

        proccessLinesTmp.IsKegItem      = this.isKegItem(proccessLinesTmp.ItemId);
        proccessLinesTmp.LineCommodity  = this.getLineCommodity(proccessLinesTmp.IsTobaccoItem, metInventItemOrderSetup.FilterCode);
        proccessLinesTmp.CaseQty_CaseLines  = (proccessLinesTmp.IsKegItem == NoYes::No && proccessLinesTmp.IsTobaccoItem == NoYes::No && proccessLinesTmp.SalesUnit != unitEA) ? proccessLinesTmp.SalesQty : 0;
        proccessLinesTmp.BrokenCasesCountSecurity = proccessLinesTmp.IsTobaccoItem == NoYes::Yes ? proccessLinesTmp.SalesQty : 0;
        proccessLinesTmp.BrokenCasesCountNonSecurity = (proccessLinesTmp.IsKegItem == NoYes::No && proccessLinesTmp.IsTobaccoItem == NoYes::No && proccessLinesTmp.SalesUnit == unitEA) ? proccessLinesTmp.SalesQty : 0;
        proccessLinesTmp.RepackCountSecurity = tobaccoRepackQtyFactor ? proccessLinesTmp.BrokenCasesCountSecurity/tobaccoRepackQtyFactor : 0;
        proccessLinesTmp.RepackCountNonSecurity = standardRepackQtyFactor ? proccessLinesTmp.BrokenCasesCountNonSecurity/standardRepackQtyFactor : 0;
        proccessLinesTmp.KegQtyUOM      = this.getKegQtyUOM(_salesLine.ItemId);

        [proccessLinesTmp.LineUnitVolume, proccessLinesTmp.LineUnitWeight] = this.getLineUnitVolumeWeight(_salesLine.ItemId, _salesLine.inventDim(),_salesLine.SalesUnit);

        proccessLinesTmp.LineVolume_CaseLines  = proccessLinesTmp.CaseQty_CaseLines * proccessLinesTmp.LineUnitVolume;
        proccessLinesTmp.LineVolume_BrokenCaseSecurity = proccessLinesTmp.BrokenCasesCountSecurity * proccessLinesTmp.LineUnitVolume;
        proccessLinesTmp.LineVolume_BrokenCaseNonSecurity = proccessLinesTmp.BrokenCasesCountNonSecurity * proccessLinesTmp.LineUnitVolume;
        proccessLinesTmp.LineVolume_Kegs = proccessLinesTmp.IsKegItem ? proccessLinesTmp.SalesQty * proccessLinesTmp.LineUnitVolume : 0;
            
        proccessLinesTmp.LineWeight_BrokenCaseNonSecurity = proccessLinesTmp.BrokenCasesCountNonSecurity * proccessLinesTmp.LineUnitWeight;
        proccessLinesTmp.LineWeight_BrokenCaseSecurity = proccessLinesTmp.BrokenCasesCountSecurity * proccessLinesTmp.LineUnitWeight;
        proccessLinesTmp.LineWeight_CaseLines = proccessLinesTmp.CaseQty_CaseLines * proccessLinesTmp.LineUnitWeight;
        proccessLinesTmp.LineWeight_Kegs = proccessLinesTmp.IsKegItem ? proccessLinesTmp.SalesQty * proccessLinesTmp.LineUnitWeight : 0;

        proccessLinesTmp.insert();
    }

/// <summary>
/// Delete all records from temp table
/// </summary>
void resetTmpTable()
{
    delete_from proccessLinesTmp;
}
